@namespace Lumeo
@* shadcn's Field: one label + control + description, spaced by gap-2 (measured live
   2026-09-02). Vertical stacks them; Horizontal puts the control beside the label, which is
   the checkbox / switch shape; Responsive is Vertical until the enclosing FieldGroup is
   md-wide, then Horizontal. *@
<div role="group" data-slot="field" data-orientation="@OrientationAttr" class="@CssClass" @attributes="AdditionalAttributes">
    @ChildContent
</div>

@code {
    [Parameter] public RenderFragment? ChildContent { get; set; }

    /// <summary>Additional CSS classes, merged after the defaults.</summary>
    [Parameter] public string? Class { get; set; }

    /// <summary>Unmatched attributes splatted onto the root element.</summary>
    [Parameter(CaptureUnmatchedValues = true)] public Dictionary<string, object>? AdditionalAttributes { get; set; }

    /// <summary>How label, control and description are laid out. Default <see cref="FieldOrientation.Vertical"/>.</summary>
    [Parameter] public FieldOrientation Orientation { get; set; } = FieldOrientation.Vertical;

    public enum FieldOrientation
    {
        Vertical,
        Horizontal,
        Responsive
    }

    private string OrientationAttr => Orientation switch
    {
        FieldOrientation.Horizontal => "horizontal",
        FieldOrientation.Responsive => "responsive",
        _ => "vertical"
    };

    private string OrientationClasses => Orientation switch
    {
        FieldOrientation.Horizontal => "flex-row items-center has-[>[data-slot=field-content]]:items-start [&>[data-slot=field-label]]:flex-auto has-[>[data-slot=field-content]]:[&>[data-slot=field-label]]:pt-0.5",
        FieldOrientation.Responsive => "flex-col [&>*]:w-full [&>.sr-only]:w-auto @md/field-group:flex-row @md/field-group:items-center @md/field-group:[&>*]:w-auto @md/field-group:[&>[data-slot=field-label]]:flex-auto",
        _ => "flex-col [&>*]:w-full [&>.sr-only]:w-auto"
    };

    private string CssClass => Cx.Merge("group/field flex w-full gap-2 data-[invalid=true]:text-destructive", OrientationClasses, Class);
}

@namespace Lumeo
@* shadcn's FieldContent: wraps label + description when the control sits beside them
   (a Horizontal field), so the text column keeps its own tight rhythm. *@
<div data-slot="field-content" class="@CssClass" @attributes="AdditionalAttributes">
    @ChildContent
</div>

@code {
    [Parameter] public RenderFragment? ChildContent { get; set; }

    /// <summary>Additional CSS classes, merged after the defaults.</summary>
    [Parameter] public string? Class { get; set; }

    /// <summary>Unmatched attributes splatted onto the root element.</summary>
    [Parameter(CaptureUnmatchedValues = true)] public Dictionary<string, object>? AdditionalAttributes { get; set; }

    private string CssClass => Cx.Merge("group/field-content flex flex-1 flex-col gap-0.5 leading-snug", Class);
}

@namespace Lumeo
@* shadcn's FieldDescription. Measured live 2026-09-02: 14px, muted, leading-normal.
   A link inside it is underlined and turns primary on hover, so "Don't have an account?
   Sign up" reads the way it does in their login blocks without per-link classes. *@
<p data-slot="field-description" class="@CssClass" @attributes="AdditionalAttributes">
    @ChildContent
</p>

@code {
    [Parameter] public RenderFragment? ChildContent { get; set; }

    /// <summary>Additional CSS classes, merged after the defaults.</summary>
    [Parameter] public string? Class { get; set; }

    /// <summary>Unmatched attributes splatted onto the root element.</summary>
    [Parameter(CaptureUnmatchedValues = true)] public Dictionary<string, object>? AdditionalAttributes { get; set; }

    private string CssClass => Cx.Merge(
        "text-muted-foreground text-sm leading-normal font-normal group-has-[[data-orientation=horizontal]]/field:text-balance",
        "last:mt-0 nth-last-2:-mt-1 [[data-variant=legend]+&]:-mt-1.5",
        "[&>a]:underline [&>a]:underline-offset-4 [&>a:hover]:text-primary",
        Class);
}

@namespace Lumeo
@* shadcn's FieldError. Renders nothing when there is nothing to say: no child content and
   no messages. Several messages become a list; duplicates (the same rule firing from two
   validators) collapse to one line. *@
@if (ChildContent is not null)
{
    <div role="alert" data-slot="field-error" class="@CssClass" @attributes="AdditionalAttributes">@ChildContent</div>
}
else if (Unique.Count == 1)
{
    <div role="alert" data-slot="field-error" class="@CssClass" @attributes="AdditionalAttributes">@Unique[0]</div>
}
else if (Unique.Count > 1)
{
    <div role="alert" data-slot="field-error" class="@CssClass" @attributes="AdditionalAttributes">
        <ul class="ml-4 flex list-disc flex-col gap-1">
            @foreach (var m in Unique)
            {
                <li>@m</li>
            }
        </ul>
    </div>
}

@code {
    [Parameter] public RenderFragment? ChildContent { get; set; }

    /// <summary>Additional CSS classes, merged after the defaults.</summary>
    [Parameter] public string? Class { get; set; }

    /// <summary>Unmatched attributes splatted onto the root element.</summary>
    [Parameter(CaptureUnmatchedValues = true)] public Dictionary<string, object>? AdditionalAttributes { get; set; }

    /// <summary>
    /// Validation messages to show when there is no <see cref="ChildContent"/>. Null or
    /// empty entries are skipped and duplicates collapse, so the same rule reported twice
    /// reads once.
    /// </summary>
    [Parameter] public IEnumerable<string?>? Errors { get; set; }

    private List<string> Unique => (Errors ?? Enumerable.Empty<string?>())
        .Where(e => !string.IsNullOrWhiteSpace(e))
        .Select(e => e!)
        .Distinct(StringComparer.Ordinal)
        .ToList();

    private string CssClass => Cx.Merge("text-destructive text-sm font-normal", Class);
}

@namespace Lumeo
@* shadcn's FieldGroup: the column that spaces fields apart. Measured live 2026-09-02:
   gap 20px. It is a container-query root so a Responsive Field can switch to a row when
   the GROUP is wide enough, independent of the viewport. *@
<div data-slot="field-group" class="@CssClass" @attributes="AdditionalAttributes">
    @ChildContent
</div>

@code {
    [Parameter] public RenderFragment? ChildContent { get; set; }

    /// <summary>Additional CSS classes, merged after the defaults.</summary>
    [Parameter] public string? Class { get; set; }

    /// <summary>Unmatched attributes splatted onto the root element.</summary>
    [Parameter(CaptureUnmatchedValues = true)] public Dictionary<string, object>? AdditionalAttributes { get; set; }

    private string CssClass => Cx.Merge("group/field-group @container/field-group flex w-full flex-col gap-5", Class);
}

@namespace Lumeo
@* shadcn's FieldLabel: a Label that fits its content and, when it wraps a whole Field
   (the "clickable card" pattern), stretches to a column. *@
<Label For="@For" data-slot="field-label" Class="@CssClass" @attributes="AdditionalAttributes">
    @ChildContent
</Label>

@code {
    [Parameter] public RenderFragment? ChildContent { get; set; }

    /// <summary>Additional CSS classes, merged after the defaults.</summary>
    [Parameter] public string? Class { get; set; }

    /// <summary>Unmatched attributes splatted onto the root element.</summary>
    [Parameter(CaptureUnmatchedValues = true)] public Dictionary<string, object>? AdditionalAttributes { get; set; }

    /// <summary>Id of the control this label is for.</summary>
    [Parameter] public string? For { get; set; }

    private string CssClass => Cx.Merge(
        "group/field-label peer/field-label flex w-fit gap-2 leading-snug group-data-[disabled=true]/field:opacity-50",
        "has-[>[data-slot=field]]:w-full has-[>[data-slot=field]]:flex-col has-[>[data-slot=field]]:rounded-md has-[>[data-slot=field]]:border",
        Class);
}

@namespace Lumeo
@* shadcn's FieldLegend. Variant Legend is the fieldset title (16px/500), Label sizes it like
   a field label (14px/500) for a group of checkboxes or radios. *@
<legend data-slot="field-legend" data-variant="@(Variant == LegendVariant.Label ? "label" : "legend")" class="@CssClass" @attributes="AdditionalAttributes">
    @ChildContent
</legend>

@code {
    [Parameter] public RenderFragment? ChildContent { get; set; }

    /// <summary>Additional CSS classes, merged after the defaults.</summary>
    [Parameter] public string? Class { get; set; }

    /// <summary>Unmatched attributes splatted onto the root element.</summary>
    [Parameter(CaptureUnmatchedValues = true)] public Dictionary<string, object>? AdditionalAttributes { get; set; }

    /// <summary>Title size: <see cref="LegendVariant.Legend"/> (default) or <see cref="LegendVariant.Label"/>.</summary>
    [Parameter] public LegendVariant Variant { get; set; } = LegendVariant.Legend;

    public enum LegendVariant
    {
        Legend,
        Label
    }

    private string CssClass => Cx.Merge(
        "mb-1.5 font-medium",
        Variant == LegendVariant.Label ? "text-sm" : "text-base",
        Class);
}

@namespace Lumeo
@* shadcn's FieldSeparator: a rule between fields, optionally with a label sitting on it
   ("Or continue with"). Measured live 2026-09-02: 20px tall, pulled in by -my-2 so it
   costs the group 4px net. *@
<div data-slot="field-separator" data-content="@(ChildContent is not null ? "true" : "false")" class="@CssClass" @attributes="AdditionalAttributes">
    <Separator Class="absolute inset-0 top-1/2" />
    @if (ChildContent is not null)
    {
        <span data-slot="field-separator-content" class="text-muted-foreground relative mx-auto block w-fit bg-background px-2">@ChildContent</span>
    }
</div>

@code {
    [Parameter] public RenderFragment? ChildContent { get; set; }

    /// <summary>Additional CSS classes, merged after the defaults.</summary>
    [Parameter] public string? Class { get; set; }

    /// <summary>Unmatched attributes splatted onto the root element.</summary>
    [Parameter(CaptureUnmatchedValues = true)] public Dictionary<string, object>? AdditionalAttributes { get; set; }

    private string CssClass => Cx.Merge("relative -my-2 h-5 text-sm group-data-[variant=outline]/field-group:-mb-2", Class);
}

@namespace Lumeo
@* shadcn's FieldSet: a <fieldset> that stacks its fields. Measured live 2026-09-02: gap 16px. *@
<fieldset data-slot="field-set" class="@CssClass" @attributes="AdditionalAttributes">
    @ChildContent
</fieldset>

@code {
    [Parameter] public RenderFragment? ChildContent { get; set; }

    /// <summary>Additional CSS classes, merged after the defaults.</summary>
    [Parameter] public string? Class { get; set; }

    /// <summary>Unmatched attributes splatted onto the root element.</summary>
    [Parameter(CaptureUnmatchedValues = true)] public Dictionary<string, object>? AdditionalAttributes { get; set; }

    private string CssClass => Cx.Merge("flex flex-col gap-4", Class);
}

@namespace Lumeo
@* shadcn's FieldTitle: label typography without the <label> element, for a field whose
   control is not labelable (a group of buttons, a custom widget). *@
<div data-slot="field-label" class="@CssClass" @attributes="AdditionalAttributes">
    @ChildContent
</div>

@code {
    [Parameter] public RenderFragment? ChildContent { get; set; }

    /// <summary>Additional CSS classes, merged after the defaults.</summary>
    [Parameter] public string? Class { get; set; }

    /// <summary>Unmatched attributes splatted onto the root element.</summary>
    [Parameter(CaptureUnmatchedValues = true)] public Dictionary<string, object>? AdditionalAttributes { get; set; }

    private string CssClass => Cx.Merge("flex w-fit items-center gap-2 text-sm leading-snug font-medium group-data-[disabled=true]/field:opacity-50", Class);
}
